window.docContents[49].resolve({"/Storage-and-commands/Assignment/#Core-C______--Storage-and-commands--Assignment":{"contents":"The left side denotes a location and has the type of the right side. The order is the one C++17 fixes for assignment, the right operand before the left one. The location must be live.The implementations are partial, so Lean records opaque constants that carry the type and not the body, and no property of them is proved here.\n\n","context":"Core C++\u0009Storage and commands","header":"4.3. Assignment","id":"/Storage-and-commands/Assignment/#Core-C______--Storage-and-commands--Assignment"}});